struct stringx
{
    char *chars;
    void *my_buf;
    stringx(const stringx &);
    ~stringx();
};

typedef unsigned int color32;

class Font
{
public:
    enum HORIZJUST
    {
        HORIZJUST_LEFT,
        HORIZJUST_CENTER,
        HORIZJUST_RIGHT
    };

    enum VERTJUST
    {
        VERTJUST_TOP,
        VERTJUST_CENTER,
        VERTJUST_BOTTOM
    };
};

class TextString
{
public:
    TextString(Font *f, stringx t, float x, float y, int z, float scale,
               Font::HORIZJUST hj, Font::VERTJUST vj, color32 col)
    {
        cons(f, t, x, y, z, scale, hj, vj, false, col);
    }

    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();

protected:
    virtual void cons(Font *, stringx, float, float, int, float,
                      Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

class FlashText : public TextString
{
public:
    bool flash;
    color32 color1;
    color32 color2;
    float flash_time;
    float flash_alpha;

    FlashText(Font *, stringx, float, float, int, float,
              Font::HORIZJUST, Font::VERTJUST, color32, bool);
    virtual ~FlashText();
    virtual void Update(float);
    virtual void Draw();
};

FlashText::FlashText(Font *f, stringx t, float x, float y, int z, float scale,
                     Font::HORIZJUST hj, Font::VERTJUST vj, color32 col, bool fl)
    : TextString(f, t, x, y, z, scale, hj, vj, col)
{
    flash = fl;
    color1 = col;
    color2 = col;
    flash_time = 0.0f;
    flash_alpha = 0.0f;
}
